const QUESTIONS = [{"id": "a1", "section": "A", "title": "Soalan 1", "topic": "Pembentukan Malaysia", "intro": "Bilakah Malaysia dibentuk?", "fields": [{"id": "a1", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["31 Ogos 1957", "16 September 1963", "1 September 1962", "9 Julai 1985"], "answer": 1, "max": 1, "model": "16 September 1963. Hari Malaysia memperingati pembentukan Malaysia pada 16 September 1963."}]}, {"id": "a2", "section": "A", "title": "Soalan 2", "topic": "Pembentukan Malaysia", "intro": "Ancaman komunis merupakan satu cabaran ketika cadangan pembentukan Malaysia dikemukakan. Bagaimanakah pembentukan Malaysia membantu menghadapi cabaran ini?", "fields": [{"id": "a2", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Menghapuskan semua sempadan negara", "Menamatkan kegiatan pertanian", "Mengukuhkan kerjasama keselamatan wilayah yang bergabung", "Menyerahkan pentadbiran kepada komunis"], "answer": 2, "max": 1, "model": "Mengukuhkan kerjasama keselamatan wilayah yang bergabung. Kerjasama pertahanan dan keselamatan membantu menghadapi ancaman komunis."}]}, {"id": "a3", "section": "A", "title": "Soalan 3", "topic": "Pembentukan Malaysia", "intro": "Apakah tugas utama Suruhanjaya Cobbold?", "fields": [{"id": "a3", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Meninjau pandangan penduduk Sabah dan Sarawak tentang pembentukan Malaysia", "Mereka bentuk kereta nasional", "Mengadakan pilihan raya di semua negeri", "Memilih Perdana Menteri yang pertama"], "answer": 0, "max": 1, "model": "Meninjau pandangan penduduk Sabah dan Sarawak tentang pembentukan Malaysia. Suruhanjaya ini mendapatkan pandangan penduduk di kedua-dua wilayah tersebut."}]}, {"id": "a4", "section": "A", "title": "Soalan 4", "topic": "Pembentukan Malaysia", "intro": "Mengapakah Jawatankuasa Antara Kerajaan (JAK) ditubuhkan?", "fields": [{"id": "a4", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Menguruskan kutipan hasil getah", "Menentukan pemenang pertandingan sukan", "Menggubal lagu negeri", "Merangka peruntukan perlembagaan yang melindungi kepentingan Sabah dan Sarawak"], "answer": 3, "max": 1, "model": "Merangka peruntukan perlembagaan yang melindungi kepentingan Sabah dan Sarawak. JAK membincangkan jaminan perlembagaan dan kepentingan kedua-dua wilayah dalam persekutuan baharu."}]}, {"id": "a5", "section": "A", "title": "Soalan 5", "topic": "Pembentukan Malaysia", "intro": "Di manakah referendum berkaitan penyertaan dalam Malaysia diadakan pada 1 September 1962?", "fields": [{"id": "a5", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Singapura", "Perlis", "Melaka", "Pulau Pinang"], "answer": 0, "max": 1, "model": "Singapura. Referendum di Singapura meninjau pendirian penduduk tentang syarat penggabungan."}]}, {"id": "a6", "section": "A", "title": "Soalan 6", "topic": "Identiti dan kerajaan negara", "intro": "Apakah gelaran pemerintah negeri Perlis?", "fields": [{"id": "a6", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Sultan", "Yang di-Pertua Negeri", "Raja", "Yang di-Pertuan Besar"], "answer": 2, "max": 1, "model": "Raja. Pemerintah Perlis bergelar Raja."}]}, {"id": "a7", "section": "A", "title": "Soalan 7", "topic": "Identiti dan kerajaan negara", "intro": "Pokok pinang ialah salah satu lambang yang terdapat pada jata negeri manakah?", "fields": [{"id": "a7", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Sabah", "Pulau Pinang", "Perak", "Johor"], "answer": 1, "max": 1, "model": "Pulau Pinang. Pokok pinang berkaitan dengan asal nama Pulau Pinang."}]}, {"id": "a8", "section": "A", "title": "Soalan 8", "topic": "Identiti dan kerajaan negara", "intro": "Rakyat menghormati Perlembagaan Persekutuan sebagai undang-undang tertinggi negara. Prinsip Rukun Negara manakah berkaitan dengan tindakan ini?", "fields": [{"id": "a8", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Kepercayaan kepada Tuhan", "Kesopanan dan Kesusilaan", "Kesetiaan kepada Raja dan Negara", "Keluhuran Perlembagaan"], "answer": 3, "max": 1, "model": "Keluhuran Perlembagaan. Keluhuran Perlembagaan menekankan kedudukan dan penghormatan terhadap perlembagaan."}]}, {"id": "a9", "section": "A", "title": "Soalan 9", "topic": "Identiti dan kerajaan negara", "intro": "Apakah satu matlamat Rukun Negara?", "fields": [{"id": "a9", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Mengutamakan kepentingan satu kaum sahaja", "Mencapai perpaduan yang lebih erat dalam kalangan seluruh masyarakat", "Menghapuskan semua adat tradisional", "Mengasingkan murid mengikut agama"], "answer": 1, "max": 1, "model": "Mencapai perpaduan yang lebih erat dalam kalangan seluruh masyarakat. Perpaduan ialah matlamat Rukun Negara; matlamat berbeza daripada lima prinsipnya."}]}, {"id": "a10", "section": "A", "title": "Soalan 10", "topic": "Identiti dan kerajaan negara", "intro": "Apakah peranan Perdana Menteri?", "fields": [{"id": "a10", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Menjadi ketua negeri bagi semua negeri", "Menggantikan semua anggota Parlimen", "Mengetuai kerajaan Persekutuan dan mempengerusikan Jemaah Menteri", "Menjatuhkan hukuman dalam setiap kes mahkamah"], "answer": 2, "max": 1, "model": "Mengetuai kerajaan Persekutuan dan mempengerusikan Jemaah Menteri. Perdana Menteri memimpin pentadbiran kerajaan Persekutuan dan Jemaah Menteri."}]}, {"id": "a11", "section": "A", "title": "Soalan 11", "topic": "Masyarakat Malaysia", "intro": "Dalam sejarah ekonomi Tanah Melayu sebelum merdeka, ramai buruh Cina bekerja di kawasan lombong. Apakah hasil utama yang dilombong?", "fields": [{"id": "a11", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Bijih timah", "Getah", "Padi", "Kelapa sawit"], "answer": 0, "max": 1, "model": "Bijih timah. Perlombongan bijih timah melibatkan ramai buruh Cina. Ini konteks sejarah dan bukan pekerjaan semua anggota sesuatu kaum."}]}, {"id": "a12", "section": "A", "title": "Soalan 12", "topic": "Masyarakat Malaysia", "intro": "Apakah nama rumah ibadat penganut agama Sikh?", "fields": [{"id": "a12", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Masjid", "Gereja", "Kuil", "Gurdwara"], "answer": 3, "max": 1, "model": "Gurdwara. Gurdwara ialah rumah ibadat agama Sikh."}]}, {"id": "a13", "section": "A", "title": "Soalan 13", "topic": "Masyarakat Malaysia", "intro": "Perayaan Gawai Dayak di Sarawak berkaitan dengan kegiatan apakah?", "fields": [{"id": "a13", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Membuka lombong baharu", "Meraikan hasil tuaian", "Melancarkan kereta nasional", "Menyambut musim tengkujuh"], "answer": 1, "max": 1, "model": "Meraikan hasil tuaian. Gawai Dayak ialah perayaan masyarakat Dayak yang dikaitkan dengan kesyukuran terhadap hasil tuaian."}]}, {"id": "a14", "section": "A", "title": "Soalan 14", "topic": "Masyarakat Malaysia", "intro": "Tarian Sumazau merupakan tarian tradisional masyarakat manakah?", "fields": [{"id": "a14", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Portugis di Melaka", "Cina di Perak", "Kadazandusun di Sabah", "Sikh di Selangor"], "answer": 2, "max": 1, "model": "Kadazandusun di Sabah. Sumazau ialah tarian tradisional masyarakat Kadazandusun."}]}, {"id": "a15", "section": "A", "title": "Soalan 15", "topic": "Sejarah dan asal usul negeri", "intro": "Menurut kisah pembukaan Melaka, nama Melaka diambil sempena apakah?", "fields": [{"id": "a15", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Pokok tempat Parameswara berehat", "Nama kapal pedagang", "Nama sebuah gunung", "Nama sejenis kereta"], "answer": 0, "max": 1, "model": "Pokok tempat Parameswara berehat. Kisah asal usul nama Melaka mengaitkannya dengan pokok Melaka; soalan ini merujuk kisah tersebut."}]}, {"id": "a16", "section": "A", "title": "Soalan 16", "topic": "Tokoh negara", "intro": "Siapakah tokoh yang dikenali sebagai Bapa Kemerdekaan?", "fields": [{"id": "a16", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Tun Abdul Razak Hussein", "Tun Hussein Onn", "Tun Dr. Mahathir Mohamad", "Tunku Abdul Rahman Putra Al-Haj"], "answer": 3, "max": 1, "model": "Tunku Abdul Rahman Putra Al-Haj. Tunku Abdul Rahman memimpin usaha mencapai kemerdekaan dan merupakan Perdana Menteri pertama."}]}, {"id": "a17", "section": "A", "title": "Soalan 17", "topic": "Pembangunan negara", "intro": "Kegiatan manakah merupakan contoh kegiatan ekonomi awal masyarakat di Tanah Melayu?", "fields": [{"id": "a17", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Menghasilkan satelit komunikasi", "Menanam padi dan menangkap ikan", "Membina kereta elektrik moden", "Menghasilkan cip komputer"], "answer": 1, "max": 1, "model": "Menanam padi dan menangkap ikan. Pertanian dan perikanan merupakan kegiatan ekonomi awal."}]}, {"id": "a18", "section": "A", "title": "Soalan 18", "topic": "Pembangunan negara", "intro": "Apakah model kereta nasional pertama yang dilancarkan pada tahun 1985?", "fields": [{"id": "a18", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Perodua Kancil", "Proton Wira", "Proton Saga", "Perodua Myvi"], "answer": 2, "max": 1, "model": "Proton Saga. Proton Saga dilancarkan pada 9 Julai 1985."}]}, {"id": "a19", "section": "A", "title": "Soalan 19", "topic": "Pembangunan negara", "intro": "Datuk Nicol David mengharumkan nama Malaysia dalam sukan apakah?", "fields": [{"id": "a19", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Skuasy", "Badminton", "Terjun", "Hoki"], "answer": 0, "max": 1, "model": "Skuasy. Nicol David ialah tokoh sukan skuasy negara."}]}, {"id": "a20", "section": "A", "title": "Soalan 20", "topic": "Hubungan antarabangsa", "intro": "Apakah satu matlamat kerjasama Komanwel?", "fields": [{"id": "a20", "type": "choice", "label": "Pilih satu jawapan yang paling tepat.", "options": ["Menguasai pentadbiran semua negara anggota", "Melarang negara anggota berdagang", "Menghapuskan kedaulatan negara anggota", "Menggalakkan kerjasama, pembangunan dan keamanan negara anggota"], "answer": 3, "max": 1, "model": "Menggalakkan kerjasama, pembangunan dan keamanan negara anggota. Komanwel menggalakkan pembangunan, demokrasi, keamanan dan kerjasama."}]}, {"id": "b1", "section": "B", "title": "1. Langkah pembentukan Malaysia", "topic": "Pembentukan Malaysia", "intro": "Padankan setiap peristiwa dengan tarikh yang betul. Setiap padanan bernilai 1 markah. Pilih satu tarikh bagi setiap peristiwa.", "fields": [{"id": "b1a", "type": "select", "label": "(a) Tunku Abdul Rahman mengumumkan cadangan pembentukan Malaysia di Singapura.", "options": ["27 Mei 1961", "17 Januari 1962", "1 September 1962", "9 Julai 1963", "16 September 1963"], "answer": 0, "max": 1, "model": "27 Mei 1961"}, {"id": "b1b", "type": "select", "label": "(b) Suruhanjaya Cobbold ditubuhkan.", "options": ["27 Mei 1961", "17 Januari 1962", "1 September 1962", "9 Julai 1963", "16 September 1963"], "answer": 1, "max": 1, "model": "17 Januari 1962"}, {"id": "b1c", "type": "select", "label": "(c) Referendum diadakan di Singapura.", "options": ["27 Mei 1961", "17 Januari 1962", "1 September 1962", "9 Julai 1963", "16 September 1963"], "answer": 2, "max": 1, "model": "1 September 1962"}, {"id": "b1d", "type": "select", "label": "(d) Perjanjian Malaysia ditandatangani di London.", "options": ["27 Mei 1961", "17 Januari 1962", "1 September 1962", "9 Julai 1963", "16 September 1963"], "answer": 3, "max": 1, "model": "9 Julai 1963"}, {"id": "b1e", "type": "select", "label": "(e) Malaysia dimasyhurkan.", "options": ["27 Mei 1961", "17 Januari 1962", "1 September 1962", "9 Julai 1963", "16 September 1963"], "answer": 4, "max": 1, "model": "16 September 1963"}]}, {"id": "b2", "section": "B", "title": "2. Gelaran dan lambang negeri", "topic": "Identiti dan asal usul negeri", "intro": "Lengkapkan maklumat negeri dengan memilih jawapan yang betul. Setiap jawapan bernilai 1 markah.", "fields": [{"id": "b2a", "type": "select", "label": "(a) Gelaran pemerintah negeri Johor.", "options": ["Raja", "Sultan", "Yang di-Pertua Negeri", "Yang di-Pertuan Besar"], "answer": 1, "max": 1, "model": "Sultan"}, {"id": "b2b", "type": "select", "label": "(b) Gelaran pemerintah Negeri Sembilan.", "options": ["Yang di-Pertuan Besar", "Sultan", "Raja", "Yang di-Pertua Negeri"], "answer": 0, "max": 1, "model": "Yang di-Pertuan Besar"}, {"id": "b2c", "type": "select", "label": "(c) Gelaran ketua negeri Pulau Pinang.", "options": ["Sultan", "Raja", "Yang di-Pertua Negeri", "Yang di-Pertuan Besar"], "answer": 2, "max": 1, "model": "Yang di-Pertua Negeri"}, {"id": "b2d", "type": "select", "label": "(d) Haiwan yang menjadi penyokong perisai pada jata negeri Melaka.", "options": ["Harimau", "Pelanduk", "Gajah", "Burung kenyalang"], "answer": 1, "max": 1, "model": "Pelanduk"}, {"id": "b2e", "type": "select", "label": "(e) Asal nama Pulau Pinang dikaitkan dengan sejenis pokok, iaitu...", "options": ["Pokok Melaka", "Pokok getah", "Pokok pinang", "Pokok padi"], "answer": 2, "max": 1, "model": "Pokok pinang"}]}, {"id": "b3", "section": "B", "title": "3. Agama dan rumah ibadat", "topic": "Masyarakat Malaysia", "intro": "Padankan agama dengan rumah ibadat yang sesuai. Untuk agama Buddha dalam set padanan ini, gunakan wat. Setiap padanan bernilai 1 markah.", "fields": [{"id": "b3a", "type": "select", "label": "(a) Islam", "options": ["Masjid", "Gereja", "Kuil", "Wat", "Gurdwara"], "answer": 0, "max": 1, "model": "Masjid"}, {"id": "b3b", "type": "select", "label": "(b) Kristian", "options": ["Masjid", "Gereja", "Kuil", "Wat", "Gurdwara"], "answer": 1, "max": 1, "model": "Gereja"}, {"id": "b3c", "type": "select", "label": "(c) Hindu", "options": ["Masjid", "Gereja", "Kuil", "Wat", "Gurdwara"], "answer": 2, "max": 1, "model": "Kuil"}, {"id": "b3d", "type": "select", "label": "(d) Buddha", "options": ["Masjid", "Gereja", "Kuil", "Wat", "Gurdwara"], "answer": 3, "max": 1, "model": "Wat. Tokong dan vihara juga merupakan rumah ibadat sesetengah penganut Buddha; wat ialah pilihan yang disediakan dalam padanan ini."}, {"id": "b3e", "type": "select", "label": "(e) Sikh", "options": ["Masjid", "Gereja", "Kuil", "Wat", "Gurdwara"], "answer": 4, "max": 1, "model": "Gurdwara"}]}, {"id": "b4", "section": "B", "title": "4. Ekonomi, sukan dan hubungan luar", "topic": "Pembangunan dan hubungan antarabangsa", "intro": "Pilih jawapan yang betul bagi setiap pernyataan. Setiap jawapan bernilai 1 markah.", "fields": [{"id": "b4a", "type": "select", "label": "(a) Sebelum merdeka, ramai buruh India yang tinggal di ladang terlibat dalam kegiatan...", "options": ["Perladangan getah", "Pembuatan kapal terbang", "Pembuatan cip komputer", "Pembuatan satelit"], "answer": 0, "max": 1, "model": "Perladangan getah. Ini konteks sejarah sebahagian masyarakat di kawasan ladang, bukan pekerjaan semua orang India."}, {"id": "b4b", "type": "select", "label": "(b) Malaysia menjadi tuan rumah Sukan Komanwel di Kuala Lumpur pada tahun...", "options": ["1957", "1963", "1985", "1998"], "answer": 3, "max": 1, "model": "1998"}, {"id": "b4c", "type": "select", "label": "(c) Datuk Lee Chong Wei ialah tokoh sukan...", "options": ["Skuasy", "Terjun", "Badminton", "Bola sepak"], "answer": 2, "max": 1, "model": "Badminton"}, {"id": "b4d", "type": "select", "label": "(d) OIC merujuk kepada pertubuhan...", "options": ["Pertubuhan Kerjasama Islam", "Persatuan Negara-negara Asia Tenggara", "Pertubuhan Bangsa-Bangsa Bersatu", "Komanwel"], "answer": 0, "max": 1, "model": "Pertubuhan Kerjasama Islam"}, {"id": "b4e", "type": "select", "label": "(e) Antara matlamat OIC ialah...", "options": ["Menamatkan semua hubungan diplomatik", "Mengeratkan perpaduan dan kerjasama negara anggota", "Menghapuskan budaya semua negara anggota", "Melarang kerjasama pendidikan"], "answer": 1, "max": 1, "model": "Mengeratkan perpaduan dan kerjasama negara anggota"}]}, {"id": "c1", "section": "C", "title": "1. Perayaan dan perpaduan masyarakat", "topic": "Masyarakat Malaysia", "intro": "Sekolah Kebangsaan Harmoni akan mengadakan sambutan perayaan yang melibatkan murid pelbagai kaum. Setiap kumpulan akan memperkenalkan makanan, pakaian dan kesenian tradisional. Jawab menggunakan ayat sendiri.", "fields": [{"id": "c1a", "type": "text", "label": "(a) Nyatakan dua kepentingan sambutan perayaan pelbagai kaum di Malaysia.", "max": 2, "model": "Mana-mana dua isi berbeza, 1 markah setiap isi: mengeratkan perpaduan / hubungan masyarakat; memupuk sikap hormat atau toleransi; mengenali adat dan budaya kaum lain; memelihara warisan budaya. Isi yang sama diulang tidak mendapat markah tambahan.", "concepts": [["perpaduan", "silaturahim", "hubungan", "muhibah", "muhibbah"], ["hormat", "toleransi"], ["mengenali", "memahami", "pengetahuan", "mempelajari"], ["warisan", "memelihara budaya", "mengekalkan budaya"]]}, {"id": "c1b", "type": "text", "label": "(b) Cadangkan satu aktiviti yang boleh dijalankan semasa sambutan itu. Jelaskan bagaimana aktiviti tersebut melibatkan murid pelbagai kaum dan kesannya terhadap perpaduan.", "max": 3, "model": "Contoh: Mengadakan persembahan tarian tradisional secara berkumpulan (1). Murid pelbagai kaum berlatih dan bekerjasama dalam satu kumpulan (1), lalu lebih memahami budaya rakan dan mengeratkan hubungan (1). Terima aktiviti lain yang sesuai dengan penjelasan dan kesan yang sepadan. Pecahan: aktiviti 1 + penglibatan bersama 1 + kesan 1.", "rules": [[["tarian", "persembahan", "pameran", "jamuan", "rumah terbuka", "kuiz", "permainan", "bengkel", "masakan", "pakaian"]], [["bersama", "bekerjasama", "pelbagai kaum", "campuran", "semua kaum"]], [["perpaduan", "hubungan", "memahami", "hormat", "silaturahim", "muhibah", "muhibbah"]]]}]}, {"id": "c2", "section": "C", "title": "2. Sukan mengharumkan nama negara", "topic": "Pembangunan negara", "intro": "Malaysia pernah menjadi tuan rumah Sukan Komanwel pada tahun 1998. Atlet seperti Nicol David dan Lee Chong Wei pula mengharumkan nama negara melalui pencapaian sukan mereka.", "fields": [{"id": "c2a", "type": "text", "label": "(a) Nyatakan dua faedah penganjuran sukan antarabangsa kepada Malaysia.", "max": 2, "model": "Mana-mana dua isi berbeza, 1 markah setiap isi: meningkatkan pendapatan negara / peniaga; menarik pelancong; memperkenalkan / menaikkan imej negara; menyediakan atau menaik taraf kemudahan sukan; mewujudkan peluang pekerjaan; mengeratkan perpaduan atau hubungan antarabangsa. Terima isi munasabah yang berkaitan.", "concepts": [["pendapatan", "ekonomi", "jualan", "perniagaan"], ["pelancong", "pelancongan"], ["imej", "terkenal", "nama negara", "memperkenalkan negara"], ["kemudahan", "infrastruktur", "stadium"], ["pekerjaan", "peluang kerja"], ["perpaduan", "hubungan"]]}, {"id": "c2b", "type": "text", "label": "(b) Sebagai murid, cadangkan satu tindakan untuk menghargai jasa atlet negara. Jelaskan cara melakukannya dan satu kesan positif tindakan itu.", "max": 3, "model": "Contoh: Menghasilkan buku skrap tentang atlet negara (1). Mencatat dan berkongsi kisah latihan serta pencapaian mereka dengan rakan (1), supaya murid menghargai usaha atlet dan mencontohi sikap gigih (1). Terima contoh lain seperti memberi sokongan berhemah: menyokong atlet (1), memberi kata semangat tanpa menghina ketika kalah (1), meningkatkan motivasi / semangat atlet (1). Pecahan: tindakan 1 + pelaksanaan 1 + kesan 1.", "rules": [[["buku skrap", "poster", "sokong", "sokongan", "penghargaan", "mencontohi", "menghargai", "pameran"]], [["berkongsi", "mencatat", "kata semangat", "tidak menghina", "tanpa menghina", "membaca", "menulis", "mempelajari", "menceritakan"]], [["gigih", "motivasi", "semangat", "bangga", "menghargai", "inspirasi", "disiplin", "cinta negara"]]]}]}];
